"""Labelled evaluation dataset for the MUSK retrieval loop.

Faithful Python port of ``src/eval.dataset.ts``. Data only: importing this
module has no side effects. The three case lists (33 knowledge-base cases, 259
development paraphrases, 118 held-out paraphrases) are captured literally so the
evaluation scores are byte-for-byte comparable with the TypeScript harness.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Literal

KbParaphraseCategory = Literal["answerable", "must-escalate", "ambiguous", "protected"]


@dataclass(frozen=True)
class KbEvalCase:
    id: str
    question: str
    expected_passage_id: str | None


@dataclass(frozen=True)
class KbParaphraseCase:
    id: str
    question: str
    category: KbParaphraseCategory
    expected_passage_id: str | None


